let activeNodeId = 'sw-core';
let activePortNum = null;
let searchQuery = '';
let currentSidebarTab = 'nodes';
let isAssetEditable = false;
let tempUploadedImage = '';

// Declaración global explícita para evitar problemas de carga o ámbito
window.handleDeviceTypeChange = function(selectedType) {
    const pcContainer = document.getElementById('hw-pc-container');
    const printerContainer = document.getElementById('hw-printer-container');
    const genericContainer = document.getElementById('hw-generic-container');
    const genericTitle = document.getElementById('genericHardwareTitle');
    const swInstitutionalBlock = document.getElementById('sw-institutional-block');

    if (!pcContainer || !printerContainer || !genericContainer) return;

    // Ocultar todo por defecto
    pcContainer.style.display = 'none';
    printerContainer.style.display = 'none';
    genericContainer.style.display = 'none';
    if (swInstitutionalBlock) swInstitutionalBlock.style.display = 'block';

    if (selectedType === 'PC' || selectedType === 'Notebook') {
        pcContainer.style.display = 'flex';
    } else if (selectedType === 'Impresora') {
        printerContainer.style.display = 'flex';
        if (swInstitutionalBlock) swInstitutionalBlock.style.display = 'none';
    } else {
        genericContainer.style.display = 'flex';
        if (selectedType === 'Access Point') {
            genericTitle.innerText = "Configuración de Red / Inalámbrica (AP)";
        } else if (selectedType === 'Equipo Clínico') {
            genericTitle.innerText = "Especificación Biomédica / Clínica";
        } else if (selectedType === 'Switch') {
            genericTitle.innerText = "Gestión de Switch / Enlace Troncal";
        }
        if (swInstitutionalBlock) swInstitutionalBlock.style.display = 'none';
    }
};

function saveNetStorage() {
    localStorage.setItem('hfc_net_saas_db', JSON.stringify(hospitalNetworkNodes));
}

// Agrega o adapta esta función de búsqueda en tu script principal para que escanee 
// de forma global en todos los switches y nodos del hospital al escribir en el input de búsqueda.

function setupGlobalIpSearch() {
    const searchInput = document.querySelector('#ip-search-input') || document.querySelector('input[type="text"]');
    if (!searchInput) return;

    searchInput.addEventListener('input', (e) => {
        const query = e.target.value.toLowerCase().trim();
        if (!query) {
            resetIpViewToDefault();
            return;
        }

        let globalMatches = [];

        // Recorrer todos los nodos y sus puertos para buscar coincidencia en IP u hostname
        hospitalNetworkNodes.forEach(node => {
            if (node.ports) {
                Object.keys(node.ports).forEach(portKey => {
                    let port = node.ports[portKey];
                    let ipStr = (port.ip || '').toLowerCase();
                    let hostStr = (port.hostname || '').toLowerCase();
                    let macStr = (port.mac || '').toLowerCase();

                    if (ipStr.includes(query) || hostStr.includes(query) || macStr.includes(query)) {
                        globalMatches.log = true;
                        globalMatches.push({
                            nodeId: node.id,
                            nodeName: node.name,
                            rack: node.rack,
                            piso: node.piso,
                            portKey: portKey,
                            portData: port
                        });
                    }
                });
            }
        });

        renderGlobalSearchResults(globalMatches, query);
    });
}

function renderGlobalSearchResults(results, query) {
    const container = document.querySelector('#ips-list-container') || document.querySelector('.ips-sidebar-container');
    if (!container) return;

    container.innerHTML = `<div class="search-header-results">Resultados globales para: "${query}" (${results.length})</div>`;
    
    if (results.length === 0) {
        container.innerHTML += `<div class="no-results">No se encontraron coincidencias en la subred.</div>`;
        return;
    }

    results.forEach(item => {
        let card = document.createElement('div');
        card.className = `ip-result-card ${item.portData.enabled ? 'occupied' : 'free'}`;
        card.innerHTML = `
            <div class="ip-info">
                <strong>${item.portData.ip}</strong> (${item.portData.hostname})
            </div>
            <div class="switch-location">
                <small>${item.nodeName} [Rack: ${item.rack} - ${item.piso}] - Puerto ${item.portKey}</small>
            </div>
        `;
        
        // Al hacer clic, navega o selecciona automáticamente el switch y puerto correspondiente
        card.onclick = () => {
            selectSwitchNode(item.nodeId);
            highlightPortOnUI(item.portKey);
        };
        
        container.appendChild(card);
    });
}

// Ejecutar al iniciar la aplicación
document.addEventListener('DOMContentLoaded', () => {
    setupGlobalIpSearch();
});

function filterNetworkNodes() {
    searchQuery = document.getElementById('netSearchInput').value.toLowerCase();
    switchSidebarTab(currentSidebarTab);
}

function renderNetworkApp() {
    renderTopologyBar();
    renderChassis();
    renderCharts();
    switchSidebarTab(currentSidebarTab);
}

function switchSidebarTab(tab) {
    currentSidebarTab = tab;
    const list = document.getElementById('netNodesListContainer');
    const counter = document.getElementById('nodeCounter');
    if (!list) return;

    if (counter) counter.innerText = hospitalNetworkNodes.length;

    const currentSelectedNode = hospitalNetworkNodes.find(s => s.id === activeNodeId);
    const baseSubnet = "10.66.50.";

    if (tab === 'nodes') {
        let usedIpsMap = {};
        hospitalNetworkNodes.forEach(node => {
            if(node.ip) usedIpsMap[node.ip] = true;
            if(node.ports) {
                Object.values(node.ports).forEach(port => {
                    if(port.ip) usedIpsMap[port.ip] = true;
                });
            }
        });

        let freeList = [];
        for(let i = 1; i <= 254; i++) {
            let currentIp = `${baseSubnet}${i}`;
            if(!usedIpsMap[currentIp]) {
                if (currentIp.includes(searchQuery)) {
                    freeList.push(currentIp);
                }
            }
        }

        let freeHtml = freeList.map(ip => `
            <div style="background: rgba(16,185,129,0.08); border: 1px solid rgba(16,185,129,0.2); padding: 5px 8px; border-radius: 4px; display: flex; justify-content: space-between; align-items: center; font-family: monospace; font-size: 0.6rem;">
                <span style="color: var(--success); font-weight: 700;">${ip}</span>
                <span style="font-size: 0.5rem; color: var(--text-muted);">Disponible</span>
            </div>
        `).join('');

list.innerHTML = `
    <div style="font-size: 0.6rem; font-weight: 700; color: var(--success); margin-bottom: 6px;">🟢 IPs Libres en Subred (${freeList.length})</div>
    <div style="display: flex; flex-direction: column; gap: 4px; overflow-y: auto; flex: 1; min-height: 0;">
        ${freeHtml || '<div style="color:var(--text-muted); font-size:0.6rem; text-align:center; padding:10px;">Sin coincidencias</div>'}
    </div>
`;
    } else if (tab === 'syslog') {
        let nodeIps = [];
        
        if (currentSelectedNode) {
            if (currentSelectedNode.ip && (currentSelectedNode.ip.includes(searchQuery) || currentSelectedNode.name.toLowerCase().includes(searchQuery))) {
                nodeIps.push({ ip: currentSelectedNode.ip, desc: `${currentSelectedNode.name} (Management)` });
            }
            if (currentSelectedNode.ports) {
                Object.entries(currentSelectedNode.ports).forEach(([portNum, port]) => {
                    if (port.ip) {
                        let rosetaInfo = port.roseta ? ` [Roseta: ${port.roseta}]` : '';
                        let descText = `Puerto #${portNum} - ${port.hostname || 'Dispositivo'}${rosetaInfo}`;
                        if (port.ip.includes(searchQuery) || descText.toLowerCase().includes(searchQuery)) {
                            nodeIps.push({ ip: port.ip, desc: descText });
                        }
                    }
                });
            }
        }

        let nodeIpHtml = nodeIps.length > 0 ? nodeIps.map(item => `
            <div onclick="openAssetInventoryModal('${item.ip}')" style="background: var(--surface-card); border: 1px solid var(--border); padding: 6px 8px; border-radius: 4px; display: flex; flex-direction: column; gap: 2px; font-family: monospace; font-size: 0.55rem; cursor: pointer; transition: 0.2s;" onmouseover="this.style.borderColor='var(--accent)'" onmouseout="this.style.borderColor='var(--border)'">
                <div style="display: flex; justify-content: space-between;">
                    <span style="color: var(--accent); font-weight: 700;">${item.ip}</span>
                    <span style="color: var(--success);">Ver Ficha ➔</span>
                </div>
                <div style="color: var(--text-muted); font-size: 0.5rem;">${item.desc}</div>
            </div>
        `).join('') : `
            <div style="padding: 12px; font-size: 0.6rem; color: var(--text-muted); text-align: center; line-height: 1.4;">
                <i class="fas fa-network-wired" style="color: var(--accent); font-size: 1rem; margin-bottom: 4px;"></i><br>
                <b>${currentSelectedNode ? currentSelectedNode.rack : ''}</b> no tiene equipos con IP asignada.
            </div>
        `;

        list.innerHTML = `
            <div style="font-size: 0.6rem; font-weight: 700; color: var(--accent); margin-bottom: 6px;">
                🔵 Asignadas en: ${currentSelectedNode ? currentSelectedNode.rack : ''}
            </div>
            <div style="display: flex; flex-direction: column; gap: 4px; max-height: calc(100vh - 280px); overflow-y: auto;">
                ${nodeIpHtml}
            </div>
        `;
    }
}

function renderTopologyBar() {
    const bar = document.getElementById('topologyBarContainer');
    if (!bar) return;
    bar.innerHTML = '';

    bar.style.display = 'flex';
    bar.style.alignItems = 'center';
    bar.style.gap = '10px';
    bar.style.overflowX = 'auto';

    const core = hospitalNetworkNodes.find(s => s.coreHub);
    let coreHtml = '';
    if (core) {
        coreHtml = `<div class="map-node core-hub ${core.id === activeNodeId ? 'active-pin' : ''}" onclick="activeNodeId='${core.id}'; activePortNum=null; closePortInspector(); renderNetworkApp();"><i class="fas fa-network-wired"></i><span>${core.name}</span></div>`;
    }

    const f1 = hospitalNetworkNodes.filter(s => !s.coreHub && s.piso === 'Primer Piso');
    const f2 = hospitalNetworkNodes.filter(s => !s.coreHub && s.piso === 'Segundo Piso');

    // Función auxiliar corregida para recibir el prefijo del piso (ej: 'P1' o 'P2')
    const renderRackPairs = (switches, floorPrefix) => {
        let html = '';
        for (let i = 0; i < switches.length; i += 2) {
            let pair = switches.slice(i, i + 2);
            let rackLetter = String.fromCharCode(65 + (i / 2)); // A, B, C...
            html += `<div style="display: flex; align-items: center; gap: 4px; background: rgba(255,255,255,0.03); padding: 2px 4px; border-radius: 4px; border: 1px dashed var(--border);">
                <span style="font-size: 0.5rem; color: var(--text-muted); margin-right: 2px;">${floorPrefix}-${rackLetter}:</span>`;
            pair.forEach(sw => {
                html += `<div class="map-node ${sw.id === activeNodeId ? 'active-pin' : ''}" onclick="activeNodeId='${sw.id}'; activePortNum=null; closePortInspector(); renderNetworkApp();" style="margin: 0;"><i class="fas fa-server"></i><span>${sw.name}</span></div>`;
            });
            html += `</div>`;
        }
        return html;
    };

    bar.innerHTML = `
        <div style="display: flex; align-items: center; gap: 6px;">
            ${coreHtml}
        </div>
        <div style="width: 1px; height: 18px; background: var(--border);"></div>
        <div style="display: flex; align-items: center; gap: 8px;">
            <span style="font-size: 0.6rem; font-weight: bold; color: var(--success); white-space: nowrap;"><i class="fas fa-building"></i> 1° Piso:</span>
            ${renderRackPairs(f1, 'P1')}
        </div>
        <div style="width: 1px; height: 18px; background: var(--border);"></div>
        <div style="display: flex; align-items: center; gap: 8px;">
            <span style="font-size: 0.6rem; font-weight: bold; color: var(--warning, #f59e0b); white-space: nowrap;"><i class="fas fa-building"></i> 2° Piso:</span>
            ${renderRackPairs(f2, 'P2')}
        </div>
    `;
}

