// Maneja el evento de clic derecho (contextmenu) para eliminar la conexión completamente
function handlePatchRightClick(event, patchPortNum) {
    event.preventDefault(); // Evita el menú contextual por defecto del navegador
    
    const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
    if (!sw) return;

    const rackSwitches = hospitalNetworkNodes.filter(s => s.rack === sw.rack);
    let foundAndDisconnected = false;

    rackSwitches.forEach(node => {
        if (node.ports) {
            Object.keys(node.ports).forEach(swPortKey => {
                let portData = node.ports[swPortKey];
                if (portData.patchPort && parseInt(portData.patchPort) === patchPortNum) {
                    // Limpieza completa de datos y vista de conexión
                    delete portData.patchPort;
                    portData.enabled = false;
                    portData.hostname = '';
                    portData.ip = '';
                    portData.mac = '';
                    
                    foundAndDisconnected = true;
                }
            });
        }
    });

    if (foundAndDisconnected) {
        saveNetStorage();
        renderNetworkApp();
        
        const terminalScreen = document.getElementById('netTerminalScreen');
        if (terminalScreen) {
            terminalScreen.innerHTML += `<div><code style="color: var(--danger);">[PATCH] Conexión eliminada: Puerto de Patch Panel #${patchPortNum} liberado y limpiado.</code></div>`;
            terminalScreen.scrollTop = terminalScreen.scrollHeight;
        }
    }
}

function renderDataRow(start, end, typePrefix = 'D', startNum = 1) {
    let html = '<div style="display: flex; gap: 6px; width: 100%; justify-content: space-between;">';
    let totalGrupos = 5; 

    for (let g = 0; g < totalGrupos; g++) {
        html += '<div style="display: grid; grid-template-columns: repeat(6, 1fr); gap: 2px; flex: 1; width: 100%; background: #090d13; padding: 3px; border-radius: 2px; border: 1px solid #1e293b; box-shadow: inset 0 1px 3px rgba(0,0,0,0.8);">';
        
        for (let i = 0; i < 6; i++) {
            let portNum = (g * 6) + i + 1;
            if (portNum <= (end - start + 1)) {
                let actualId = start + portNum - 1;
                
                let assignedLabel = `${typePrefix}${portNum < 10 ? '0' + portNum : portNum}`;
                let isLinked = false;
                let linkTitle = `Patch #${actualId} (Click izq: Enlazar | Click der: Limpiar)`;
                
                const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
                if (sw && sw.ports) {
                    Object.entries(sw.ports).forEach(([swPortKey, portData]) => {
                        if (portData.patchPort && parseInt(portData.patchPort) === actualId) {
                            isLinked = true;
                            let hostName = portData.hostname || portData.ip || `SW P#${swPortKey}`;
                            assignedLabel = `${typePrefix}${portNum < 10 ? '0' + portNum : portNum}<br><span style="font-size:7px; color:var(--accent); font-weight:bold;">${hostName}</span>`;
                            linkTitle = `Patch #${actualId} ➔ Enlazado a Puerto Switch #${swPortKey} (${hostName})`;
                        }
                    });
                }

                // RECUPERADO: Verificar si este puerto es el que estaba seleccionado actualmente
                let isSelected = (typeof window.persistentSelectedPort !== 'undefined' && window.persistentSelectedPort === actualId);
                
                let bgColor = isSelected ? '#1e3a8a' : (isLinked ? '#0b192c' : '#1e293b');
                let borderColor = isSelected ? '#3b82f6' : (isLinked ? 'var(--accent)' : 'transparent');

                html += `<div class="port-item ${isLinked ? 'patch-linked' : ''} ${isSelected ? 'selected-port' : ''}" data-port="${actualId}" 
                             onclick="openPatchPanelLinkModal(${actualId})" 
                             oncontextmenu="handlePatchRightClick(event, ${actualId})"
                             style="background: ${bgColor}; border: 1px solid ${borderColor}; height: 26px; border-radius: 1px; display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 8.5px; color: ${isLinked || isSelected ? '#fff' : '#94a3b8'}; cursor: pointer; text-align: center; line-height: 1;"
                             title="${linkTitle}">
                             ${assignedLabel}
                         </div>`;
            } else {
                html += '<div></div>';
            }
        }
        html += '</div>';
    }
    html += '</div>';
    return html;
}

function renderVoiceRow(start, end, typePrefix = 'V', startNum = 1) {
    let html = '<div style="display: flex; gap: 6px; width: 100%; justify-content: space-between;">';
    let totalGrupos = Math.ceil((end - start + 1) / 6);

    for (let g = 0; g < totalGrupos; g++) {
        html += '<div style="display: grid; grid-template-columns: repeat(6, 1fr); gap: 2px; flex: 1; width: 100%; background: #090d13; padding: 3px; border-radius: 2px; border: 1px solid #1e293b; box-shadow: inset 0 1px 3px rgba(0,0,0,0.8);">';
        
        for (let i = 0; i < 6; i++) {
            let portNum = (g * 6) + i + 1;
            if (portNum <= (end - start + 1)) {
                let actualId = start + portNum - 1;
                let voicePortIndex = startNum + portNum - 1;
                
                let assignedLabel = `${typePrefix}${voicePortIndex < 10 ? '0' + voicePortIndex : voicePortIndex}`;
                let isLinked = false;
                let linkTitle = `Patch Voz #${actualId} (Click izq: Enlazar | Click der: Limpiar)`;
                
                const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
                if (sw && sw.ports) {
                    Object.entries(sw.ports).forEach(([swPortKey, portData]) => {
                        if (portData.patchPort && parseInt(portData.patchPort) === actualId) {
                            isLinked = true;
                            let hostName = portData.hostname || portData.ip || `SW P#${swPortKey}`;
                            assignedLabel = `${typePrefix}${voicePortIndex < 10 ? '0' + voicePortIndex : voicePortIndex}<br><span style="font-size:7px; color:var(--warning, #f59e0b); font-weight:bold;">${hostName}</span>`;
                            linkTitle = `Patch Voz #${actualId} ➔ Enlazado a Puerto Switch #${swPortKey} (${hostName})`;
                        }
                    });
                }

                // RECUPERADO: Verificar selección activa también para voz
                let isSelected = (typeof window.persistentSelectedPort !== 'undefined' && window.persistentSelectedPort === actualId);
                
                let bgColor = isSelected ? '#3f301d' : (isLinked ? '#291e0b' : '#1e293b');
                let borderColor = isSelected ? '#f59e0b' : (isLinked ? 'var(--warning, #f59e0b)' : 'transparent');

                html += `<div class="port-item ${isLinked ? 'patch-linked' : ''} ${isSelected ? 'selected-port' : ''}" data-port="${actualId}" 
                             onclick="openPatchPanelLinkModal(${actualId})" 
                             oncontextmenu="handlePatchRightClick(event, ${actualId})"
                             style="background: ${bgColor}; border: 1px solid ${borderColor}; height: 26px; border-radius: 1px; display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 8.5px; color: ${isLinked || isSelected ? '#fff' : '#94a3b8'}; cursor: pointer; text-align: center; line-height: 1;"
                             title="${linkTitle}">
                             ${assignedLabel}
                         </div>`;
            } else {
                html += '<div></div>';
            }
        }
        html += '</div>';
    }
    html += '</div>';
    return html;
}

function openPatchPanelLinkModal(patchPortNum) {
    const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
    if (!sw) return;

    let freeSwitchPorts = [];
    for (let p = 1; p <= 24; p++) {
        let isUsed = sw.ports && sw.ports[p];
        freeSwitchPorts.push({ 
            num: p, 
            used: !!isUsed, 
            details: isUsed ? (isUsed.hostname || isUsed.type || 'Ocupado') : 'Libre' 
        });
    }

    let existingModal = document.getElementById('patchLinkModal');
    if (existingModal) existingModal.remove();

    let modal = document.createElement('div');
    modal.id = 'patchLinkModal';
    modal.style.cssText = "position: fixed; inset: 0; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 9999; backdrop-filter: blur(2px);";
    
    let optionsHtml = freeSwitchPorts.map(sp => {
        // Formatear el número de puerto como #01, #02...
        let portNumStr = `#${String(sp.num).padStart(2, '0')}`;
        
        return `
            <div onclick="linkPatchToSwitch(${patchPortNum}, ${sp.num})" 
                 style="background: ${sp.used ? 'rgba(239,68,68,0.04)' : 'rgba(16,185,129,0.06)'}; border: 1px solid ${sp.used ? 'rgba(239,68,68,0.15)' : 'rgba(16,185,129,0.25)'}; padding: 5px 8px; border-radius: 4px; display: flex; flex-direction: column; gap: 1px; cursor: pointer; font-family: monospace; transition: 0.15s;" 
                 onmouseover="this.style.background='rgba(56,189,248,0.12)'" 
                 onmouseout="this.style.background='${sp.used ? 'rgba(239,68,68,0.04)' : 'rgba(16,185,129,0.06)'}'">
                <span style="color: var(--accent); font-weight: bold; font-size: 0.6rem;">${portNumStr}</span>
                <span style="color: ${sp.used ? 'var(--danger)' : 'var(--success)'}; font-size: 0.6rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${sp.used ? sp.details : 'Disponible'}</span>
            </div>
        `;
    }).join('');

    modal.innerHTML = `
        <div style="background: var(--surface-card); border: 1px solid var(--border); border-radius: 8px; width: 520px; height: 460px; display: flex; flex-direction: column; overflow: hidden; box-shadow: 0 10px 25px rgba(0,0,0,0.5);">
            <div style="background: var(--surface-main); padding: 10px 14px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center;">
                <span style="font-size: 0.9rem; color: var(--accent); font-weight: 700; font-family: monospace;">Enlazar Patch Panel P#${patchPortNum}</span>
                <button onclick="document.getElementById('patchLinkModal').remove()" style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 0.8rem;">✕</button>
            </div>
            <div style="padding: 10px; display: flex; flex-direction: column; gap: 6px; overflow-y: auto; flex: 1;">
                <div style="font-size: 0.7rem; color: var(--text-muted); margin-bottom: 2px;">Seleccione un puerto libre <b>${sw.name} (${sw.rack})</b>:</div>
                <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px;">
                    ${optionsHtml}
                </div>
            </div>
        </div>
    `;

    document.body.appendChild(modal);
}

function linkPatchToSwitch(patchPortNum, switchPortNum) {
    const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
    if (!sw) return;

    // Obtener todos los switches del mismo rack (ej: SW-03 y SW-04 del Rack P1-B)
    const rackSwitches = hospitalNetworkNodes.filter(s => s.rack === sw.rack);

    // Limpiar primero cualquier enlace previo en este puerto de patch para evitar duplicados fantasma
    hospitalNetworkNodes.forEach(node => {
        if (node.ports) {
            Object.keys(node.ports).forEach(pKey => {
                if (node.ports[pKey].patchPort === patchPortNum) {
                    delete node.ports[pKey].patchPort;
                }
            });
        }
    });

    // Registrar el nuevo enlace en el switch seleccionado actualmente
    if (!sw.ports) sw.ports = {};
    if (!sw.ports[switchPortNum]) sw.ports[switchPortNum] = {};
    
    sw.ports[switchPortNum].patchPort = patchPortNum;
    sw.ports[switchPortNum].type = sw.ports[switchPortNum].type || 'Patch Cord';
    sw.ports[switchPortNum].enabled = true;

    saveNetStorage();
    renderNetworkApp();
    
    const modal = document.getElementById('patchLinkModal');
    if (modal) modal.remove();
}

function renderPatchCordsConnections() {
    const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
    if (!sw || !sw.ports) return '';

    let svgLines = '';
    
    // Recorrer los puertos del switch para buscar los que tienen enlace de patch panel
    Object.entries(sw.ports).forEach(([switchPortKey, portData]) => {
        if (portData.patchPort) {
            let pNum = parseInt(portData.patchPort);
            // Color de cable: Azul para Datos (D), Amarillo para Voz (V)
            let lineColor = pNum <= 48 ? '#38bdf8' : '#f59e0b'; 
            
            // Generar una línea de conexión ortogonal (estilo canaleta de rack)
            svgLines += `
                <g title="Patch #${pNum} ➔ Switch Puerto #${switchPortKey}">
                    <line x1="50%" y1="15%" x2="50%" y2="85%" stroke="${lineColor}" stroke-width="2" stroke-opacity="0.6" stroke-dasharray="4" style="animation: pulseCable 2s infinite;" />
                </g>
            `;
        }
    });

    return svgLines;
}

function selectPort(num) {
    activePortNum = num;
    renderChassis();
    
    // Ocultar y cerrar permanentemente el drawer lateral al hacer clic
    const drawer = document.getElementById('portInspectorDrawer');
    if (drawer) drawer.classList.remove('open');
}

function toggleAssetEditMode() {
    isAssetEditable = !isAssetEditable;
    const inputs = document.querySelectorAll('#assetInventoryFormBody input, #assetInventoryFormBody select, #assetInventoryFormBody textarea');
    const footer = document.getElementById('drawerActionsFooter');
    const iconEl = document.getElementById('editToggleIcon');
    const textEl = document.getElementById('editToggleText');

    inputs.forEach(el => {
        if(el.id !== 'invIp') { 
            el.disabled = !isAssetEditable;
        }
    });

    if (footer) footer.style.display = isAssetEditable ? 'block' : 'none';
    if (iconEl && textEl) {
        if (isAssetEditable) {
            iconEl.className = "fas fa-unlock-alt";
            iconEl.style.color = "var(--success)";
            textEl.innerText = "Edición Activa";
            textEl.style.color = "var(--success)";
        } else {
            iconEl.className = "fas fa-lock";
            iconEl.style.color = "var(--text-muted)";
            textEl.innerText = "Modo Lectura";
            textEl.style.color = "var(--text-muted)";
        }
    }
}

