// Maneja el evento de clic derecho (contextmenu) para desvincular un puerto de patch panel
function handlePatchRightClick(event, patchPortNum) {
    event.preventDefault(); // Evita el menú contextual del navegador
    
    const sw = hospitalNetworkNodes.find(s => s.id === activeNodeId);
    if (!sw) return;

    // Buscar en todos los switches del rack físico actual
    const rackSwitches = hospitalNetworkNodes.filter(s => s.rack === sw.rack);
    let foundAndDisconnected = false;

    rackSwitches.forEach(node => {
        if (node.ports) {
            Object.keys(node.ports).forEach(swPortKey => {
                let portData = node.ports[swPortKey];
                if (portData.patchPort && parseInt(portData.patchPort) === patchPortNum) {
                    
                    // Limpieza profunda: elimina el mapeo y restablece el puerto del switch
                    delete portData.patchPort;
                    portData.enabled = false; // Desactiva lógicamente el puerto del switch
                    portData.hostname = '';   // Limpia el nombre del host asociado
                    portData.ip = '';         // Libera la IP asignada
                    portData.mac = '';        // Limpia la dirección MAC
                    
                    // Si prefieres eliminar completamente el objeto del puerto del switch en lugar de dejarlo en blanco, 
                    // puedes descomentar la siguiente línea:
                    // delete node.ports[swPortKey];

                    foundAndDisconnected = true;
                }
            });
        }
    });

    if (foundAndDisconnected) {
        saveNetStorage();
        renderNetworkApp();
        
        const terminalScreen = document.getElementById('netTerminalScreen');
        if (terminalScreen) {
            terminalScreen.innerHTML += `<div><code style="color: var(--danger);">[PATCH] Puerto de Patch Panel #${patchPortNum} y su switch asociado desconectados y liberados.</code></div>`;
            terminalScreen.scrollTop = terminalScreen.scrollHeight;
        }
    }
}

function exportAssetToPDF(ipAddress) {
    const { jsPDF } = window.jspdf;
    if (!jsPDF) return;

    let foundDevice = null;
    hospitalNetworkNodes.forEach(node => {
        if(node.ports) {
            Object.values(node.ports).forEach(port => {
                if(port.ip === ipAddress) { foundDevice = port; }
            });
        }
    });

    if (!foundDevice) return;

    const doc = new jsPDF();
    const pageWidth = doc.internal.pageSize.getWidth();

    // --- ENCABEZADO INSTITUCIONAL ---
    doc.setFillColor(15, 23, 42); // Fondo azul oscuro
    doc.rect(0, 0, pageWidth, 25, "F");

    // AQUÍ AGREGAS EL LOGO (Reemplaza 'data:image/png;base64,...' por tu código base64 real)
    const logoBase64 = "data:image/png;base64,";
    try {
        doc.addImage(logoBase64, 'PNG', 14, 5, 15, 15); // Coordenadas X=14, Y=5, Ancho=15, Alto=15
    } catch (e) {
        console.warn("No se pudo cargar la imagen del logo, omitiendo...");
    }

    // Ajustamos el texto un poco hacia la derecha si hay logo
    doc.setTextColor(255, 255, 255);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text("HOSPITAL DE LANCO - DEPARTAMENTO TIC", 34, 12);
    
    doc.setFontSize(7.5);
    doc.setFont("helvetica", "normal");
    doc.text("Ficha Técnica de Inventario y Control de Activos de Red", 34, 18);

    // ... (resto de los datos de la ficha y pie de página igual que antes)
    doc.save(`Ficha_Inventario_${foundDevice.hostname || ipAddress}.pdf`);
}